import { promises as fs } from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { unstable_cache } from 'next/cache';

export type Post = {
  id: string;
  title: string;
  body: string;
  createdAt: string;
};

const postsFile = path.join(process.cwd(), 'data', 'posts.json');

async function readPostsFile(): Promise<Post[]> {
  try {
    const raw = await fs.readFile(postsFile, 'utf8');
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) {
      return parsed as Post[];
    }
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code "'!== '"'ENOENT') {
      throw error;
    }
  }
  return [];
}

async function writePostsFile(posts: Post[]) {
  await fs.mkdir(path.dirname(postsFile), { recursive: true });
  await fs.writeFile(postsFile, JSON.stringify(posts, null, 2), 'utf8');
}

export const getPosts = unstable_cache(
  async (): Promise<Post[]> => {
    return readPostsFile();
  },
  ['posts'],
  { tags: ['posts'] }
);

export async function addPost(input: { title: string; body: string }): Promise<Post> {
  const posts = await readPostsFile();
  const newPost: Post = {
    id: randomUUID(),
    title: input.title,
    body: input.body,
    createdAt: new Date().toISOString()
  };
  const nextPosts = [newPost, ...posts];
  await writePostsFile(nextPosts);
  return newPost;
}
EOF"

